// cldapi.dll is plain C ABI - no COM, no cgo.
var (
	cldApi = windows.NewLazySystemDLL("cldapi.dll")
	procCfGetPlaceholderStateFromFindData = cldApi.NewProc("CfGetPlaceholderStateFromFindData")
)

const (
	CF_PLACEHOLDER_STATE_NO_STATES         = 0x00000000
	CF_PLACEHOLDER_STATE_PLACEHOLDER       = 0x00000001
	CF_PLACEHOLDER_STATE_SYNC_ROOT         = 0x00000002
	CF_PLACEHOLDER_STATE_IN_SYNC           = 0x00000008
	CF_PLACEHOLDER_STATE_PARTIAL           = 0x00000010
	CF_PLACEHOLDER_STATE_PARTIALLY_ON_DISK = 0x00000020
	CF_PLACEHOLDER_STATE_INVALID           = 0xffffffff

	FILE_ATTRIBUTE_OFFLINE                = 0x00001000
	FILE_ATTRIBUTE_RECALL_ON_DATA_ACCESS  = 0x00400000 // only kernel mode may SET this; we only test it
	FILE_ATTRIBUTE_RECALL_ON_OPEN         = 0x00040000 // collides with FILE_ATTRIBUTE_EA; valid ONLY from dir enumeration
	IO_REPARSE_TAG_CLOUD                  = 0x9000001A // _1.._F are 0x9000N01A
)

// fd comes straight from windows.FindFirstFile/FindNextFile - zero extra I/O.
func placeholderState(fd *windows.Win32finddata) uint32 {
	r, _, _ := procCfGetPlaceholderStateFromFindData.Call(uintptr(unsafe.Pointer(fd)))
	return uint32(r)
}

func wouldHydrate(fd *windows.Win32finddata) bool {
	st := placeholderState(fd)
	if st == CF_PLACEHOLDER_STATE_INVALID {
		// fall back to raw attribute test
		return fd.FileAttributes&FILE_ATTRIBUTE_RECALL_ON_DATA_ACCESS != 0
	}
	return st&CF_PLACEHOLDER_STATE_PARTIALLY_ON_DISK != 0
}

import "golang.org/x/sys/windows/registry"

func enumUninstall(root registry.Key, path string, view uint32) ([]string, error) {
	k, err := registry.OpenKey(root, path, registry.ENUMERATE_SUB_KEYS|registry.QUERY_VALUE|view)
	if err != nil {
		return nil, err
	}
	defer k.Close()
	return k.ReadSubKeyNames(-1)
}

