const (
	FILE_SHARE_ALL             = windows.FILE_SHARE_READ | windows.FILE_SHARE_WRITE | windows.FILE_SHARE_DELETE
	FILE_FLAG_BACKUP_SEMANTICS = 0x02000000
	FILE_FLAG_SEQUENTIAL_SCAN  = 0x08000000
