import { WorkerEntrypoint } from "cloudflare:workers";

export default class extends WorkerEntrypoint<Env> {
  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);
    if (url.pathname === "/api/checkout") return createCheckout(request, this.env);
    if (url.pathname === "/api/submit")   return submitBuild(request, this.env);
    if (url.pathname.startsWith("/api/console/")) return buildConsole(request, this.env, this.ctx);
    if (url.pathname.startsWith("/api/")) return Response.json({ error: "not_found" }, { status: 404 });
    return this.env.ASSETS.fetch(request); // reachable only if run_worker_first matched
  }
}

// ---- SSE ----------------------------------------------------------------
function sseHeaders() {
  return {
    "Content-Type": "text/event-stream; charset=utf-8",
    "Cache-Control": "no-cache, no-transform",
    "Content-Encoding": "identity", // workerd PR #7390 is still OPEN: compressed SSE buffers
    "Connection": "keep-alive",
    "X-Accel-Buffering": "no"
  };
}

async function buildConsole(request: Request, env: Env, ctx: ExecutionContext) {
  const runId = new URL(request.url).pathname.split("/").pop()!;
  const lastId = request.headers.get("Last-Event-ID");
  const { readable, writable } = new TransformStream();
  const w = writable.getWriter();
  const enc = new TextEncoder();
  const send = (event: string, data: unknown, id?: string) =>
    w.write(enc.encode(`${id ? `id: ${id}\n` : ""}event: ${event}\ndata: ${JSON.stringify(data)}\n\n`));

  ctx.waitUntil((async () => {
    const ka = setInterval(() => w.write(enc.encode(": keepalive\n\n")).catch(() => {}), 15000);
    try {
      const seen = new Set<string>(lastId ? lastId.split(",") : []);
      for (;;) {
        const token = await installationToken(env);
        const r = await gh(`/repos/${env.GH_OWNER}/${env.GH_REPO}/actions/runs/${runId}/jobs?per_page=100`, token);
        const { jobs } = await r.json<any>();
        for (const job of jobs) for (const s of job.steps ?? []) {
          const key = `${job.id}:${s.number}:${s.status}:${s.conclusion ?? ""}`;
          if (seen.has(key)) continue;
          seen.add(key);
          await send("step", { job: job.name, step: s.name, status: s.status, conclusion: s.conclusion,
                               started_at: s.started_at, completed_at: s.completed_at }, key);
        }
        if (jobs.every((j: any) => j.status === "completed")) {
          const failed = jobs.some((j: any) => j.conclusion !== "success");
          // logs only become downloadable NOW (302 -> expires in 60s); 404 while running
          await send("done", { conclusion: failed ? "failure" : "success" });
          break;
        }
        await new Promise((r) => setTimeout(r, 2500)); // sleeping costs 0 CPU time
      }
    } finally { clearInterval(ka); await w.close().catch(() => {}); }
  })());

  return new Response(readable, { headers: sseHeaders() });
}

const ALGO = { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" } as const;
const API = "https://api.github.com";
const H = (t: string) => ({ Authorization: `Bearer ${t}`, Accept: "application/vnd.github+json",
                            "X-GitHub-Api-Version": "2022-11-28", "User-Agent": "configurator-worker" });

const b64url = (b: Uint8Array) => { let s = ""; for (const x of b) s += String.fromCharCode(x);
  return btoa(s).replace(/=/g, "").replace(/\+/g, "-").replace(/\//g, "_"); };
const j64 = (o: unknown) => b64url(new TextEncoder().encode(JSON.stringify(o)));
const pemBytes = (pem: string) => { const b = atob(pem.replace(/-----[^-]+-----/g, "").replace(/\s+/g, ""));
  const u = new Uint8Array(b.length); for (let i = 0; i < b.length; i++) u[i] = b.charCodeAt(i); return u; };

function derLen(n: number): number[] {
  if (n < 0x80) return [n];
  const b: number[] = []; let v = n; while (v > 0) { b.unshift(v & 0xff); v >>= 8; }
  return [0x80 | b.length, ...b];
}
// SEQUENCE { OID 1.2.840.113549.1.1.1 rsaEncryption, NULL }
const RSA_ALG_ID = [0x30,0x0d,0x06,0x09,0x2a,0x86,0x48,0x86,0xf7,0x0d,0x01,0x01,0x01,0x05,0x00];
/** Wrap a PKCS#1 RSAPrivateKey DER in a PKCS#8 PrivateKeyInfo, because WebCrypto only imports pkcs8. */
function pkcs1ToPkcs8(pkcs1: Uint8Array): Uint8Array {
  const inner = [0x02, 0x01, 0x00, ...RSA_ALG_ID, 0x04, ...derLen(pkcs1.length)];
  const body = new Uint8Array(inner.length + pkcs1.length);
  body.set(inner, 0); body.set(pkcs1, inner.length);
  const head = [0x30, ...derLen(body.length)];
  const out = new Uint8Array(head.length + body.length);
  out.set(head, 0); out.set(body, head.length);
  return out;
}

export async function appJwt(issuer: string, pem: string): Promise<string> {
  const norm = pem.includes("\\n") ? pem.replace(/\\n/g, "\n") : pem;
  if (norm.includes("BEGIN OPENSSH PRIVATE KEY")) throw new Error("OpenSSH keys are not supported by WebCrypto");
  let der = pemBytes(norm);
  if (norm.includes("BEGIN RSA PRIVATE KEY")) der = pkcs1ToPkcs8(der);
  const key = await crypto.subtle.importKey("pkcs8", der, ALGO, false, ["sign"]);
  const iat = Math.floor(Date.now() / 1000) - 60;          // 60s back: clock drift (GitHub docs)
  const input = `${j64({ alg: "RS256", typ: "JWT" })}.${j64({ iat, exp: iat + 540, iss: issuer })}`; // exp <= 10 min
  const sig = await crypto.subtle.sign(ALGO.name, key, new TextEncoder().encode(input));
  return `${input}.${b64url(new Uint8Array(sig))}`;
}

let cached: { token: string; exp: number } | null = null; // per-isolate cache
export async function installationToken(env: Env): Promise<string> {
  if (cached && cached.exp - 60_000 > Date.now()) return cached.token;
  const jwt = await appJwt(env.GH_APP_ID, env.GH_PRIVATE_KEY);
  const inst = await fetch(`${API}/repos/${env.GH_OWNER}/${env.GH_REPO}/installation`, { headers: H(jwt) });
  if (!inst.ok) throw new Error(`installation lookup ${inst.status}: ${await inst.text()}`);
  const { id } = await inst.json<{ id: number }>();
  const res = await fetch(`${API}/app/installations/${id}/access_tokens`, {
    method: "POST", headers: { ...H(jwt), "Content-Type": "application/json" },
    body: JSON.stringify({ permissions: { contents: "write", pull_requests: "write", actions: "read" } })
  });
  if (!res.ok) throw new Error(`token ${res.status}: ${await res.text()}`);
  const { token, expires_at } = await res.json<{ token: string; expires_at: string }>();
  cached = { token, exp: Date.parse(expires_at) };         // 1 hour
  return token;
}

export async function gh(path: string, token: string, init: RequestInit = {}) {
  const r = await fetch(`${API}${path}`, { ...init,
    headers: { ...H(token), "Content-Type": "application/json", ...(init.headers ?? {}) } });
  if (!r.ok) throw new Error(`${init.method ?? "GET"} ${path} -> ${r.status}: ${await r.text()}`);
  return r;
}

/** Multi-file PR, one commit. Files: { "path/in/repo.json": "utf8 contents" }. */
export async function openPullRequest(env: Env, opts: {
  base: string; branch: string; message: string; title: string; body: string;
  files: Record<string, string>; draft?: boolean;
}) {
  const t = await installationToken(env);
  const R = `/repos/${env.GH_OWNER}/${env.GH_REPO}`;

  // 1. base ref  (path form is heads/<branch>, NOT refs/heads/<branch>)
  const ref = await (await gh(`${R}/git/ref/heads/${opts.base}`, t)).json<any>();
  const baseSha: string = ref.object.sha;

  // 2. base commit -> its tree
  const baseCommit = await (await gh(`${R}/git/commits/${baseSha}`, t)).json<any>();

  // 3. tree. tree[].content inlines the blob, so POST /git/blobs is unnecessary for text.
  //    modes: 100644 file, 100755 exec, 040000 tree, 160000 submodule, 120000 symlink. sha:null deletes.
  const tree = await (await gh(`${R}/git/trees`, t, { method: "POST", body: JSON.stringify({
    base_tree: baseCommit.tree.sha,
    tree: Object.entries(opts.files).map(([path, content]) => ({ path, mode: "100644", type: "blob", content }))
  })})).json<any>();

  // 4. commit
  const commit = await (await gh(`${R}/git/commits`, t, { method: "POST", body: JSON.stringify({
    message: opts.message, tree: tree.sha, parents: [baseSha]
  })})).json<any>();

  // 5. branch ref — must be fully qualified
  await gh(`${R}/git/refs`, t, { method: "POST",
    body: JSON.stringify({ ref: `refs/heads/${opts.branch}`, sha: commit.sha }) });

  // 6. PR (triggers notifications; secondary rate limit: 80/min, 500/hr content-creating)
  return (await gh(`${R}/pulls`, t, { method: "POST", body: JSON.stringify({
    title: opts.title, head: opts.branch, base: opts.base, body: opts.body, draft: opts.draft ?? false
  })})).json<{ number: number; html_url: string; head: { sha: string } }>();
}

