type Siteverify = { success: boolean; "error-codes"?: string[]; challenge_ts?: string;
                    hostname?: string; action?: string; cdata?: string };

async function verifyTurnstile(env: Env, token: string | null, ip: string | null, action: string) {
  if (!token || token.length > 2048) return false;              // documented max length
  const body = new FormData();
  body.append("secret", env.TURNSTILE_SECRET);
  body.append("response", token);
  if (ip) body.append("remoteip", ip);
  body.append("idempotency_key", crypto.randomUUID());          // safe retries
  const r = await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify",
                        { method: "POST", body });
  const v = await r.json<Siteverify>();
  return v.success && v.action === action && v.hostname === env.PUBLIC_HOSTNAME;
}

