panel.addWidget("org.kde.plasma.pager")
panel.addWidget("org.kde.plasma.icontasks")
panel.addWidget("org.kde.plasma.marginsseparator")

panel.addWidget("org.kde.plasma.systemtray")
panel.addWidget("org.kde.plasma.digitalclock")
panel.addWidget("org.kde.plasma.showdesktop")

/*
 * Custom Welcome Center page. Numbered files in
 * /usr/share/plasma/plasma-welcome/extra-pages/ are inserted into the wizard
 * in filename order, just before the "Get Involved" page.
 * Root item must inherit Kirigami.Page; GenericPage / ScrollablePage / KCMPage
 * are provided by org.kde.plasma.welcome.
 */
import QtQuick
import QtQuick.Controls as QQC2
import QtQuick.Layouts
import org.kde.kirigami as Kirigami

import org.kde.plasma.welcome

GenericPage {
    heading: i18nc("@info:window", "Pick your apps")
    description: i18nc("@info:usagetip", "Choose anything you'd like installed. You can add or remove apps any time from the Apps icon on your taskbar.")

    ColumnLayout {
        anchors.centerIn: parent
        spacing: Kirigami.Units.largeSpacing

        QQC2.Button {
            Layout.fillWidth: true
            icon.name: "office-chart-area"
            text: i18nc("@action:button", "Install the Office suite")
            onClicked: Controller.runCommand("flatpak install -y --noninteractive flathub org.libreoffice.LibreOffice", callback)

            property var callback: (returnStatus, outputText) => {
                if (returnStatus == 0) {
                    showPassiveNotification(i18n("Office suite installed."));
                } else {
                    showPassiveNotification(outputText);
                }
            }
        }

        QQC2.Button {
            Layout.fillWidth: true
            icon.name: "printer"
            text: i18nc("@action:button", "Set up a printer")
            onClicked: Controller.runCommand("systemsettings kcm_printer_manager")
        }
    }
}
